"""Wide highway approach with a backing path; physical precedence remains unresolved."""
import xml.etree.ElementTree as ET

CONFLICT={'x_min_m':8,'x_max_m':16,'y_min_m':-5,'y_max_m':-1}


def open_drive():
    root=ET.Element('OpenDRIVE')
    ET.SubElement(root,'header',revMajor='1',revMinor='4',name='C230259 backing highway draft',version='1',date='2026-11-23',north='20',south='-20',east='80',west='-80',vendor='worker')
    road=ET.SubElement(root,'road',id='1',name='eastbound highway with backing approach',length='160',junction='-1')
    ET.SubElement(road,'link')
    geometry=ET.SubElement(ET.SubElement(road,'planView'),'geometry',s='0',x='-80',y='0',hdg='0',length='160')
    ET.SubElement(geometry,'line')
    ET.SubElement(ET.SubElement(road,'elevationProfile'),'elevation',s='0',a='0',b='0',c='0',d='0')
    section=ET.SubElement(ET.SubElement(road,'lanes'),'laneSection',s='0')
    ET.SubElement(section,'left');center=ET.SubElement(section,'center')
    ET.SubElement(center,'lane',id='0',type='none',level='false')
    right=ET.SubElement(section,'right');lane=ET.SubElement(right,'lane',id='-1',type='driving',level='false')
    ET.SubElement(lane,'width',sOffset='0',a='9',b='0',c='0',d='0')
    ET.SubElement(road,'objects');ET.SubElement(road,'signals')
    return ET.tostring(root,encoding='unicode')


def check():
    width=float(ET.fromstring(open_drive()).find('road/lanes/laneSection/right/lane/width').get('a'))
    if width!=9 or CONFLICT['y_max_m']!=-1:raise ValueError('Authored highway geometry differs')
    return {'passed':True,'road_width_m':width,'conflict_region':CONFLICT,
            'section_stem_recovered':True,'right_of_way_determined':False}

"""Original Native backing/other-moving-vehicle draft; --check is CARLA-free."""
import argparse
import json
import math
from pathlib import Path
import queue
import subprocess

from layout import CONFLICT,check as layout_check,open_drive

FRAMES=600
CAMERAS=(('overview',1920,1080,10,-14,18,-65),('approach',1280,720,22,-11,6,-25),
         ('reference_corner',1280,720,-10,-10,7,-30),('driver_reference',1280,720,12,9,9,-35))


def check():
    cfg=json.loads(Path('config.json').read_text())
    if cfg['cell_id']!='C230259' or cfg['law_id']!='NRS-484B-113-3' or cfg['case_suffix'] not in ('controlled_1','controlled_2','pedestrian_1','pedestrian_2'):
        raise ValueError('Exact assignment differs')
    if cfg['rate_hz']!=20 or cfg['duration_s']!=30 or len(CAMERAS)!=4:raise ValueError('Capture policy differs')
    if cfg.get('other_start_x_m',-35) not in (-35,-45) or cfg.get('ego_start_x_m',23) not in (23,27):
        raise ValueError('Unreviewed engineering start position')
    return {'passed':True,'geometry':layout_check(),'frame_count':FRAMES,
            'section_stem_recovered':True,'native_imported':False,'physical_acceptance_claimed':False}


def actor_row(actor):
    transform=actor.get_transform();velocity=actor.get_velocity()
    return {'actor_id':actor.id,'blueprint_id':actor.type_id,
        'center_xy_m':[transform.location.x,transform.location.y],
        'body_xy_m':[[p.x,p.y] for p in actor.bounding_box.get_world_vertices(transform)],
        'velocity_xy_mps':[velocity.x,velocity.y],
        'speed_mps':math.hypot(velocity.x,velocity.y)}


def execute(output,host,port):
    import carla
    from pipeline_capture import PipelineCapture
    from worker_exchange.native_output import FrameMap
    from worker_exchange.world_restore import snapshot,restore
    cfg=json.loads(Path('config.json').read_text());check();output=Path(output).resolve()
    if not output.is_dir() or not (output/'config.json').is_file():
        raise ValueError('Use fresh materialized exact-case output')
    client=carla.Client(host,port);client.set_timeout(180)
    old=client.get_world();saved=snapshot(client)
    if old.get_settings().synchronous_mode or any(a.type_id.startswith(('vehicle.','walker.','sensor.','controller.')) for a in old.get_actors()):
        raise RuntimeError('Exclusive idle asynchronous Native world required')
    owned=[];encoders={};queues={};changed=False;capture=None
    try:
        world=client.generate_opendrive_world(open_drive(),carla.OpendriveGenerationParameters(
            vertex_distance=.5,max_road_length=50,wall_height=0,additional_width=0,
            smooth_junctions=False,enable_mesh_visibility=True,enable_pedestrian_navigation=False))
        changed=True;settings=world.get_settings();settings.synchronous_mode=True
        settings.fixed_delta_seconds=.05;settings.substepping=True
        settings.max_substep_delta_time=.01;settings.max_substeps=10;world.apply_settings(settings)
        waypoint=world.get_map().get_waypoint(carla.Location(x=12,y=-3,z=1),project_to_road=True,lane_type=carla.LaneType.Driving)
        if waypoint is None or waypoint.road_id!=1 or waypoint.lane_id!=-1:
            raise RuntimeError('Native highway lane readback failed')
        other_waypoint=world.get_map().get_waypoint(carla.Location(x=cfg.get('other_start_x_m',-35),y=-3,z=1),project_to_road=True,lane_type=carla.LaneType.Driving)
        if other_waypoint is None or other_waypoint.road_id!=1 or other_waypoint.lane_id!=-1:
            raise RuntimeError('Moving-traffic highway route readback failed')
        bp=world.get_blueprint_library().find('vehicle.tesla.model3')
        ego=world.try_spawn_actor(bp,carla.Transform(carla.Location(x=cfg.get('ego_start_x_m',23),y=-7,z=1.2),carla.Rotation(yaw=0)))
        other=world.try_spawn_actor(bp,carla.Transform(carla.Location(x=cfg.get('other_start_x_m',-35),y=-3,z=1.2),carla.Rotation(yaw=0)))
        if ego is None or other is None:raise RuntimeError('Original vehicle spawn failed')
        if ego.id==other.id or not ego.type_id.startswith('vehicle.') or not other.type_id.startswith('vehicle.'):
            raise RuntimeError('Distinct original vehicle classification failed')
        owned.extend((ego,other))
        pedestrian=None
        if cfg['case_suffix'].startswith('pedestrian_'):
            walker_bp=next((item for item in world.get_blueprint_library().filter('walker.pedestrian.*') if item.id),None)
            if walker_bp is None:raise RuntimeError('Pedestrian blueprint unavailable')
            pedestrian=world.try_spawn_actor(walker_bp,carla.Transform(carla.Location(x=12,y=4,z=1.2),carla.Rotation(yaw=-90)))
            if pedestrian is None or not pedestrian.type_id.startswith('walker.pedestrian.'):
                raise RuntimeError('Original pedestrian spawn failed')
            owned.append(pedestrian)
        for name,width,height,x,y,z,pitch in CAMERAS:
            cbp=world.get_blueprint_library().find('sensor.camera.rgb')
            for key,value in (('image_size_x',width),('image_size_y',height),('fov',85),('sensor_tick',.05)):
                cbp.set_attribute(key,str(value))
            sensor=world.spawn_actor(cbp,carla.Transform(carla.Location(x=x,y=y,z=z),carla.Rotation(pitch=pitch)))
            owned.append(sensor);received=queue.Queue();sensor.listen(received.put);queues[name]=received
            encoders[name]=subprocess.Popen(['ffmpeg','-nostdin','-hide_banner','-loglevel','error','-n',
                '-f','rawvideo','-pix_fmt','bgra','-s',f'{width}x{height}','-r','20','-i','-',
                '-frames:v',str(FRAMES),'-c:v','ffv1',str(output/(name+'.mkv'))],stdin=subprocess.PIPE,stderr=subprocess.PIPE)
        capture=PipelineCapture(client,ego,output,cfg['case_id'],visibility=False,
            required_observations=cfg.get('required_atoms',[]))
        with (output/'native-motion.jsonl').open('x') as motion,FrameMap(output/'video_frames.jsonl') as frame_map:
            for index in range(FRAMES):
                # Timing is the only selected comparison variable; both cases use the same backing command.
                backing=(245<=index<335) if cfg['case_suffix'] in ('controlled_1','pedestrian_1') else (55<=index<145)
                ego.set_target_velocity(carla.Vector3D(x=-2.5 if backing else 0,y=.8 if backing else 0,z=0))
                other.set_target_velocity(carla.Vector3D(x=6 if index<300 else 0,y=0,z=0))
                if pedestrian is not None:
                    pedestrian.apply_control(carla.WalkerControl(direction=carla.Vector3D(x=0,y=-1,z=0),
                        speed=.8 if 50<=index<300 else 0))
                native=world.tick()
                original_row={'native_frame':native,'frame':native,'video_frame':index,'time_s':index/20,
                    'source_kind':'original_native','ego':actor_row(ego),'other':actor_row(other),
                    'pedestrian':actor_row(pedestrian) if pedestrian is not None else None,
                    'backing_commanded':backing}
                capture.capture(native,index/20,extra={'c230259_native':original_row})
                motion.write(json.dumps(original_row,allow_nan=False)+'\n')
                camera_frames={}
                for name,*_ in CAMERAS:
                    image=queues[name].get(timeout=30)
                    while image.frame<native:image=queues[name].get(timeout=30)
                    if image.frame!=native:raise RuntimeError('Original four-camera join differs')
                    encoders[name].stdin.write(image.raw_data);camera_frames[name]=image.frame
                frame_map.append(native,index/20,camera_native_frames=camera_frames)
        for name,process in encoders.items():
            process.stdin.close();error=process.stderr.read()
            if process.wait(timeout=180) or not (output/(name+'.mkv')).is_file():
                raise RuntimeError('Original FFV1 encoding failed: '+name+error.decode()[-400:])
        capture.close(confirmed=True);capture=None
        (output/'road.xodr').write_text(open_drive())
        (output/'traffic-context.json').write_text(json.dumps({'source_kind':'original_native',
            'cell_id':'C230259','conflict_region':CONFLICT,'section_stem_recovered':True,
            'section_source':'https://www.leg.state.nv.us/NRS/NRS-484B.html',
            'other_highway_use_reviewed':True,'other_road_id':other_waypoint.road_id,
            'other_lane_id':other_waypoint.lane_id,'other_route_direction':'increasing road s',
            'other_commanded_speed_mps':6,
            'driver_control_reviewed':True,'ego_actor_id':ego.id,'other_actor_id':other.id,
            'driver_control_source':'runner.py script controls ego target velocity per original Native frame',
            'pedestrian_presence_reviewed':True,'pedestrian_actor_count_at_start':int(pedestrian is not None),
            'pedestrian_actor_id':pedestrian.id if pedestrian is not None else None,
            'precedence_reviewed':False,'right_of_way_legal_verdict':None},indent=2)+'\n')
        return {'frames':FRAMES,'camera_names':list(queues),
            'section_stem_recovered':True,'physical_acceptance_claimed':False}
    finally:
        if capture is not None:
            try:capture.close(confirmed=False)
            except Exception:pass
        for process in encoders.values():
            if process.poll() is None:process.kill();process.wait()
        for actor in reversed(owned):
            try:
                if hasattr(actor,'stop'):actor.stop()
                actor.destroy()
            except Exception:pass
        if changed:restore(client,saved)


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true')
    parser.add_argument('--output-dir',type=Path);parser.add_argument('--host',default='localhost')
    parser.add_argument('--port',type=int,default=2000);args=parser.parse_args()
    if args.check:print(json.dumps(check()))
    else:
        if args.output_dir is None:parser.error('Original Native output directory required')
        print(json.dumps(execute(args.output_dir,args.host,args.port)))

"""Measure original backing and moving-traffic sequence without a right-of-way verdict."""
import argparse
import hashlib
import json
import math
from pathlib import Path

FRAMES=600
CAMERAS=('overview','approach','reference_corner','driver_reference')


def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()


def rows(path):
    if not path.is_file():raise ValueError('Missing required source: '+path.name)
    data=[json.loads(line) for line in path.read_text().splitlines()]
    if len(data)!=FRAMES:raise ValueError('Original source must contain 600 frames')
    return data


def xy(actor):
    value=actor.get('center_xy_m')
    if not isinstance(value,list) or len(value)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in value):
        raise ValueError('Original actor position missing')
    velocity=actor.get('velocity_xy_mps')
    if not isinstance(velocity,list) or len(velocity)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in velocity):
        raise ValueError('Original actor velocity missing')
    body=actor.get('body_xy_m')
    if not isinstance(body,list) or len(body)<4:raise ValueError('Original actor body missing')
    return value,velocity


def inside(point,region):
    return region['x_min_m']<=point[0]<=region['x_max_m'] and region['y_min_m']<=point[1]<=region['y_max_m']


def measure(attempt):
    attempt=Path(attempt);context_path=attempt/'traffic-context.json'
    motion_path=attempt/'native-motion.jsonl';frames_path=attempt/'video_frames.jsonl'
    for path in (context_path,motion_path,frames_path):
        if not path.is_file():raise ValueError('Missing required source: '+path.name)
    context=json.loads(context_path.read_text());region=context.get('conflict_region')
    if context.get('source_kind')!='original_native' or context.get('other_highway_use_reviewed') is not True or context.get('driver_control_reviewed') is not True:
        raise ValueError('Original highway-use or driver-control source unreviewed')
    if context.get('section_stem_recovered') is not True:
        raise ValueError('Parent statutory section source unreviewed')
    if not isinstance(region,dict) or any(type(region.get(k)) not in (int,float) for k in ('x_min_m','x_max_m','y_min_m','y_max_m')):
        raise ValueError('Original conflict region missing')
    motion,frames=rows(motion_path),rows(frames_path)
    previous=-1;backing=[];other_moving=[];joint=[];ego_entry=None;other_entry=None;min_gap=None
    actor_ids=None
    for index,(row,frame) in enumerate(zip(motion,frames)):
        native=row.get('native_frame')
        if type(native) is not int or native<=previous or frame.get('native_frame')!=native:
            raise ValueError('Original Native frame join differs')
        previous=native
        if row.get('video_frame')!=index or frame.get('video_frame')!=index or abs(row.get('time_s',-1)-index/20)>1e-6 or abs(frame.get('time_s',-1)-index/20)>1e-6:
            raise ValueError('Original video frame/time join differs')
        if frame.get('camera_native_frames')!={name:native for name in CAMERAS}:
            raise ValueError('Original four-camera join differs')
        ego_row,other_row=row.get('ego',{}),row.get('other',{})
        ego,ev=xy(ego_row);other,ov=xy(other_row)
        if context.get('fixture_kind')!='synthetic_diagnostic_only':
            ids=(ego_row.get('actor_id'),other_row.get('actor_id'))
            if any(type(v) is not int for v in ids) or ids[0]==ids[1] or (actor_ids is not None and ids!=actor_ids):
                raise ValueError('Distinct original vehicle actor identity missing or changed')
            actor_ids=ids
            if not all(str(v.get('blueprint_id','')).startswith('vehicle.') for v in (ego_row,other_row)):
                raise ValueError('Original vehicle classification missing')
        if ev[0]<-.1:backing.append(index)
        if math.hypot(*ov)>.1:other_moving.append(index)
        if inside(ego,region) and ego_entry is None:ego_entry=index
        if inside(other,region) and other_entry is None:other_entry=index
        if ev[0]<-.1 and math.hypot(*ov)>.1:
            joint.append(index)
            gap=math.hypot(ego[0]-other[0],ego[1]-other[1])
            min_gap=gap if min_gap is None else min(min_gap,gap)
    for name in CAMERAS:
        if not (attempt/(name+'.mkv')).is_file():raise ValueError('Missing required source: '+name+'.mkv')
    return {'format':'c230259-backing-moving-traffic-raw-sequence-v1','frame_count':FRAMES,
        'rate_hz':20,'backing_frame_count':len(backing),'other_moving_frame_count':len(other_moving),
        'simultaneous_backing_and_other_moving_frame_count':len(joint),
        'minimum_center_gap_during_simultaneous_motion_m':min_gap,
        'ego_first_conflict_region_frame':ego_entry,'other_first_conflict_region_frame':other_entry,
        'pedestrian_presence_reviewed':context.get('pedestrian_presence_reviewed') is True,
        'section_stem_recovered':context.get('section_stem_recovered') is True,
        'right_of_way_verdict':'unresolved','legal_verdict_claimed':False,'physical_acceptance_claimed':False,
        'source_sha256':{p.name:sha(p) for p in (context_path,motion_path,frames_path)},
        'camera_video_sha256':{name:sha(attempt/(name+'.mkv')) for name in CAMERAS}}


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',type=Path,required=True)
    parser.add_argument('--output',type=Path,required=True);args=parser.parse_args()
    if args.output.exists():raise ValueError('Use fresh measurement output')
    value=measure(args.attempt);args.output.write_text(json.dumps(value,indent=2,allow_nan=False)+'\n')
    print(json.dumps({'backing_frame_count':value['backing_frame_count'],
        'simultaneous_backing_and_other_moving_frame_count':value['simultaneous_backing_and_other_moving_frame_count'],
        'right_of_way_verdict':'unresolved'}))


if __name__=='__main__':main()

"""Independent source-shaped checks; this does not accept physical evidence."""
import hashlib
import json
from pathlib import Path


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def audit_attempt(attempt, report):
    attempt=Path(attempt)
    report=dict(report)
    if report.get('frame_count')!=600 or report.get('rate_hz')!=20:
        raise ValueError('Original duration or frame rate differs')
    if report.get('right_of_way_verdict')!='unresolved' or report.get('legal_verdict_claimed') is not False:
        raise ValueError('Unsupported legal right-of-way finding')
    if report.get('section_stem_recovered') is not True:
        raise ValueError('Parent section source unreviewed')
    if report.get('backing_frame_count',0)<=0 or report.get('other_moving_frame_count',0)<=0:
        raise ValueError('Backing or moving traffic absent')
    if report.get('simultaneous_backing_and_other_moving_frame_count',0)<=0:
        raise ValueError('No simultaneous backing and moving traffic')
    required=('traffic-context.json','native-motion.jsonl','video_frames.jsonl')
    for name in required:
        if report.get('source_sha256',{}).get(name)!=_sha(attempt/name):
            raise ValueError('Original source hash mismatch: '+name)
    for name in ('overview','approach','reference_corner','driver_reference'):
        source=attempt/(name+'.mkv')
        if report.get('camera_video_sha256',{}).get(name)!=_sha(source):
            raise ValueError('Original camera hash mismatch: '+name)
    return {'source_bindings_passed':True,'physical_acceptance_claimed':False}


def audit_comparison(left,right,left_config,right_config):
    a,b=dict(left),dict(right)
    if a.get('frame_count')!=b.get('frame_count') or a.get('rate_hz')!=b.get('rate_hz'):
        raise ValueError('Comparison capture timing differs')
    fixed=('cell_id','law_id','actor','duration_s','rate_hz','cameras')
    for key in fixed:
        if left_config.get(key)!=right_config.get(key):
            raise ValueError('Comparison fixed condition differs: '+key)
    if left_config.get('case_suffix')==right_config.get('case_suffix'):
        raise ValueError('Comparison timing variable absent')
    for report in (a,b):
        if report.get('right_of_way_verdict')!='unresolved':
            raise ValueError('Comparison cannot assign a legal verdict')
    return {'fixed_conditions_checked':list(fixed),'declared_difference':'backing onset timing',
            'physical_acceptance_claimed':False}
